const sentItems = $('Gmail Search Sent').all();
const receivedItems = $('Gmail Search Received').all();

const sentCount = sentItems.length;
const receivedCount = receivedItems.length;

// Count replied (sent emails that are replies)
let repliedCount = 0;
for (const item of sentItems) {
  const subject = (item.json.subject || '').toLowerCase();
  if (subject.startsWith('re:')) {
    repliedCount++;
  }
}

// Count by sender domain
const domainCounts = {};
for (const item of receivedItems) {
  const from = item.json.from || '';
  const domainMatch = from.match(/@([^>\s]+)/);
  if (domainMatch) {
    const domain = domainMatch[1];
    domainCounts[domain] = (domainCounts[domain] || 0) + 1;
  }
}

const topDomains = Object.entries(domainCounts)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 10)
  .map(([domain, count]) => `${domain}: ${count}`)
  .join(', ');

const responseRate = receivedCount > 0 ? ((repliedCount / receivedCount) * 100).toFixed(1) : '0';

return [{
  json: {
    date: new Date().toISOString().split('T')[0],
    sentCount: sentCount,
    receivedCount: receivedCount,
    repliedCount: repliedCount,
    responseRate: responseRate + '%',
    topSenderDomains: topDomains,
    totalActivity: sentCount + receivedCount
  }
}];

